const $=s=>document.querySelector(s);
const candidates=[
 {name:"Lumen",bio:"A moving visual target. Little chemical-relay stimulation.",traits:["visual target: 60 Hz","chemical relay: 5 Hz","mAL: 0 Hz"],profile:{visualHz:60,chemicalHz:5,inhibitoryHz:0}},
 {name:"Mallow",bio:"Chemical-relay stimulation with very little visual motion.",traits:["visual target: 5 Hz","chemical relay: 100 Hz","mAL: 0 Hz"],profile:{visualHz:5,chemicalHz:100,inhibitoryHz:0}},
 {name:"Nix",bio:"A visual target paired with strong mAL inhibitory-relay stimulation.",traits:["visual target: 60 Hz","chemical relay: 5 Hz","mAL: 60 Hz"],profile:{visualHz:60,chemicalHz:5,inhibitoryHz:60}},
 {name:"Quince",bio:"Strong, conflicting relay stimulation: visual, chemical and mAL together.",traits:["visual target: 60 Hz","chemical relay: 100 Hz","mAL: 60 Hz"],profile:{visualHz:60,chemicalHz:100,inhibitoryHz:60}}
];
let candidate=0,manifest,worker,running=false,paused=matchMedia("(prefers-reduced-motion: reduce)").matches,nodes=[],positions=new Map(),flashes=new Map(),spikes=[],history=[],result;
const brain=$("#brain"),raster=$("#raster");
function canvas(el){const r=el.getBoundingClientRect(),d=devicePixelRatio||1;if(el.width!==Math.round(r.width*d)||el.height!==Math.round(r.height*d)){el.width=Math.round(r.width*d);el.height=Math.round(r.height*d)}const c=el.getContext("2d");c.setTransform(d,0,0,d,0,0);return[c,r.width,r.height]}
function has(group,id){return manifest.groups[group]?.includes(id)}
function colour(n){return has("output",n.i)?"#efffd1":has("pulseSong",n.i)?"#ffd477":has("persistence",n.i)?"#f9b8ed":has("courtship",n.i)?"#cefa69":has("inhibitory",n.i)?"#ff957e":has("chemical",n.i)?"#d4a1fa":has("visual",n.i)?"#77c8ff":"#829179"}
function project(){const xs=nodes.map(n=>n.position[0]),zs=nodes.map(n=>n.position[2]),x0=Math.min(...xs),x1=Math.max(...xs),z0=Math.min(...zs),z1=Math.max(...zs);positions=new Map(nodes.map(n=>[n.i,{x:.08+.84*(n.position[0]-x0)/(x1-x0),y:.11+.7*(n.position[2]-z0)/(z1-z0),n}]))}
function drawBrain(){const[c,w,h]=canvas(brain);c.clearRect(0,0,w,h);for(const{x,y,n}of positions.values()){const f=paused?0:(flashes.get(n.i)||0);c.globalAlpha=n.type==="untyped"?.15:.3+f*.7;c.fillStyle=colour(n);c.beginPath();c.arc(x*w,y*h,1.05+f*2.4,0,Math.PI*2);c.fill();if(f)flashes.set(n.i,f*.88)}c.globalAlpha=.72;c.fillStyle="#c8d2c2";c.font='11px "Space Grotesk", sans-serif';c.fillText("BRAIN + NERVE CORD · 4,505 REAL SOMA POSITIONS SHOWN",20,h-20);c.globalAlpha=1;if(!paused||running)requestAnimationFrame(drawBrain)}
function watched(){return [...new Set([...manifest.groups.courtship,...manifest.groups.pulseSong,...manifest.groups.persistence,...manifest.groups.output])]} 
function drawRaster(){if(!manifest)return;const[c,w,h]=canvas(raster);c.clearRect(0,0,w,h);c.strokeStyle="#293125";for(let x=1;x<10;x++){c.beginPath();c.moveTo(x*w/10,0);c.lineTo(x*w/10,h);c.stroke()}const row=new Map(watched().map((id,i)=>[id,i]));for(const[ms,id]of spikes){const y=row.get(id);if(y===undefined)continue;c.fillStyle=colour({i:id});c.fillRect(ms/1000*w,y/watched().length*h,1.4,1.3)}}
function setCandidate(index){candidate=index%candidates.length;const p=candidates[candidate];$("#candidateNumber").textContent=`${String(candidate+1).padStart(2,"0")} / 04`;$("#profileName").textContent=p.name;$("#profileBio").textContent=p.bio;$("#motionTrait").textContent=p.traits[0];$("#cueTrait").textContent=`${p.traits[1]} · ${p.traits[2]}`;$("#resultTitle").textContent="Otto is ready.";$("#resultDetail").textContent="Run this controlled encounter through the full mapped graph.";$("#swipeStamp").hidden=true;$("#profileCard").className="specimen";result=null}
function interpret(r){const c=r.groupHz.courtship,s=r.groupHz.pulseSong,p=r.groupHz.persistence;if(c>=5&&s>=5)return{label:"Interested",detail:`pC1 ${c.toFixed(1)} Hz and pMP2 ${s.toFixed(1)} Hz were elevated${p?`; pCd-linked cells fired at ${p.toFixed(1)} Hz`:""}.`,stamp:"INTERESTED",kind:"right"};if(c>=2.4)return{label:"Investigating",detail:`pC1 reached ${c.toFixed(1)} Hz, but pMP2 song-pathway activity stayed at ${s.toFixed(1)} Hz. The response is mixed.`,stamp:"CHECKING",kind:"unclear"};return{label:"Not interested",detail:`pC1 remained low (${c.toFixed(1)} Hz) and pMP2 was ${s.toFixed(1)} Hz. These relays did not recruit this courtship response.`,stamp:"PASS",kind:"left"}}
function rates(r){$("#groupRates").innerHTML=[["pC1",r.courtship],["pMP2 song",r.pulseSong],["pCd-linked",r.persistence],["pIP10",r.output]].map(([n,v])=>`<span>${n}<b>${v.toFixed(1)} Hz</b></span>`).join("")}
function finish(r){running=false;result=r;const i=interpret(r),p=candidates[candidate];$("#statusDot").classList.remove("running");$("#statusLabel").textContent="COMPLETE";$("#resultTitle").textContent=i.label;$("#resultDetail").textContent=i.detail;const stamp=$("#swipeStamp");stamp.textContent=i.stamp;stamp.className=`swipe-stamp ${i.kind}`;stamp.hidden=false;$("#profileCard").classList.add(`swipe-${i.kind}`);setTimeout(()=>$("#profileCard").className="specimen",700);history.push({candidate:p.name,state:i.label,pC1Hz:r.groupHz.courtship,pMP2Hz:r.groupHz.pulseSong,pCdHz:r.groupHz.persistence,pIP10Hz:r.groupHz.output,seed:r.seed});$("#history").innerHTML=history.map(x=>`<article class="history-item ${x.state==="Interested"?"right":x.state==="Not interested"?"left":""}"><strong>${x.candidate}</strong><span><b>${x.state}</b></span><span>pC1 ${x.pC1Hz.toFixed(1)} · pMP2 ${x.pMP2Hz.toFixed(1)} Hz</span></article>`).join("");$("#sessionCount").textContent=`${history.length} encounter${history.length===1?"":"s"} completed`;$("#runButton").disabled=false;$("#runButton").textContent=candidate===3?"Run Lumen again":"Show Otto the next fly →";$("#shareButton").hidden=false;$("#downloadRun").disabled=false}
function run(){if(!manifest||running)return;if(result){setCandidate((candidate+1)%4);return}running=true;spikes=[];drawRaster();const p=candidates[candidate];$("#runButton").disabled=true;$("#runButton").textContent="Otto is reacting…";$("#statusDot").classList.add("running");$("#statusLabel").textContent="SIMULATING";$("#resultTitle").textContent="Encounter in progress";$("#resultDetail").textContent="Real network activity is propagating through the MaleCNS graph.";worker.postMessage({type:"run",id:`${candidate}-${Date.now()}`,profile:p.profile,seed:703,view:nodes.map(n=>n.i),raster:watched()})}
function message({data}){if(data.type==="loading"){$("#loadProgress").hidden=false;$("#loadProgress").value=data.progress;$("#loadNote").textContent=`Loading verified neural data: ${(data.progress*100).toFixed(0)}%`;return}if(data.type==="ready"){manifest=data.manifest;nodes=manifest.view;project();$("#mapCaption").textContent=`${manifest.neurons.toLocaleString()} neurons · ${manifest.connections.toLocaleString()} connections · loaded locally`;$("#loadProgress").hidden=true;$("#loadNote").textContent="All graph chunks passed integrity checks. The profile image is illustrative; only stated relay conditions are simulated.";$("#statusLabel").textContent="READY";$("#runButton").disabled=false;drawBrain();drawRaster();return}if(data.type==="activity"){for(const id of data.spikes)flashes.set(id,1);spikes.push(...data.rasterSpikes);$("#activeCount").textContent=data.total.toLocaleString();$("#pursuitValue").innerHTML=`${data.outputHz.toFixed(1)}<small> Hz</small>`;$("#timeValue").innerHTML=`${Math.round(data.ms)}<small> ms</small>`;rates(data.groupHz);drawRaster();return}if(data.type==="result")return finish(data);if(data.type==="error"){running=false;$("#statusLabel").textContent="ERROR";$("#resultTitle").textContent="The encounter could not run.";$("#resultDetail").textContent=data.message;$("#runButton").disabled=false}}
worker=new Worker(new URL("./brain-worker.js",import.meta.url),{type:"module"});worker.onmessage=message;worker.postMessage({type:"load"});$("#runButton").disabled=true;$("#runButton").addEventListener("click",run);$("#motionToggle").addEventListener("click",()=>{paused=!paused;$("#motionToggle").textContent=paused?"Show flashes":"Reduce flashes";if(!paused)requestAnimationFrame(drawBrain)});$("#viewToggle").addEventListener("click",()=>{brain.classList.toggle("focus");$("#viewToggle").textContent=brain.classList.contains("focus")?"Show whole CNS":"Focus on brain"});$("#shareButton").addEventListener("click",async()=>{const url=new URL(location.href);url.hash=`candidate=${candidate}`;try{await navigator.clipboard.writeText(url);$("#shareButton").textContent="Encounter link copied ✓"}catch{location.hash=`candidate=${candidate}`;$("#shareButton").textContent="Link is in the address bar"}});$("#downloadRun").addEventListener("click",()=>{const blob=new Blob([JSON.stringify({dataset:manifest.dataset,parameters:"MaleCNS LIF model; fixed seed 703",encounters:history},null,2)],{type:"application/json"}),a=Object.assign(document.createElement("a"),{href:URL.createObjectURL(blob),download:"otto-encounters.json"});a.click();URL.revokeObjectURL(a.href)});for(const id of["scienceOpen","modelOpen"])$("#"+id).addEventListener("click",()=>$("#science").showModal());$("#scienceClose").addEventListener("click",()=>$("#science").close());window.addEventListener("resize",()=>{if(manifest){drawRaster();requestAnimationFrame(drawBrain)}});const shared=new URLSearchParams(location.hash.slice(1)).get("candidate");if(/^[0-3]$/.test(shared||""))candidate=Number(shared);setCandidate(candidate);
